const appLocale = "en-AU";

const formatterCurrencyWithoutCents = new Intl.NumberFormat(appLocale,
  {
    style: "currency", currency: "AUD", maximumFractionDigits: 0,
  });

export function formatCurrencyWithoutCents(value: string | number | null | undefined) {
  const valueAsNumber = Number(value);
  if (!value || !valueAsNumber) { return ""; }

  return formatterCurrencyWithoutCents.format(valueAsNumber);
}

const formatterNumberGeneral = new Intl.NumberFormat(appLocale);

export function formatNumberGeneral(value: string | number | null | undefined) {
  const valueAsNumber = Number(value);
  if (!value || !valueAsNumber) { return ""; }

  return formatterNumberGeneral.format(valueAsNumber);
}
